function allInternalMembers(){return state.customerGroups.flatMap(group=>(group.members||[]).map(member=>({...member,groupId:group.id})))}
function ensureGroupMembersDialog(){let dialog=$('#groupMembersDialog');if(dialog)return dialog;dialog=document.createElement('dialog');dialog.id='groupMembersDialog';dialog.className='modal-xl';document.body.append(dialog);return dialog}
function openGroupMembers(g,editingId=null){if(!window.__omniplaySession?.superAdmin)return;g.members||=[];const editing=g.members.find(member=>member.id===editingId),dialog=ensureGroupMembersDialog();dialog.innerHTML=`<div class="dialog-form group-members-dialog"><div class="modal-head"><div><div class="eyebrow">INTERNAL MEMBERS</div><h3>${esc(g.name)}－人員管理</h3><p>管理此群組的人員與登入帳密。</p></div><button type="button" class="icon-close" data-member-close>×</button></div><form id="groupMemberForm" class="group-member-form"><label>人員名稱<input id="groupMemberName" required maxlength="60" value="${esc(editing?.name||'')}" placeholder="輸入姓名"/></label><label>登入帳號<input id="groupMemberUsername" required maxlength="80" value="${esc(editing?.username||'')}" autocomplete="off" placeholder="輸入登入帳號"/></label><label>登入密碼<input id="groupMemberPassword" required type="password" maxlength="120" value="${esc(editing?.password||'')}" autocomplete="new-password" placeholder="輸入登入密碼"/></label><button class="primary" type="submit">${editing?'儲存變更':'＋ 新增人員'}</button>${editing?'<button class="secondary" type="button" id="cancelMemberEdit">取消編輯</button>':''}</form><div class="group-member-list">${g.members.length?g.members.map(member=>`<div class="group-member-row"><div class="customer-avatar">${esc((member.name||'?').slice(0,1).toUpperCase())}</div><div class="group-member-main"><strong>${esc(member.name)}</strong><span>帳號：${esc(member.username)}</span></div><button type="button" class="group-member-edit" data-member-edit="${member.id}">編輯</button><button type="button" class="group-member-delete" data-member-delete="${member.id}">刪除</button></div>`).join(''):'<div class="empty-mini"><div>👤</div><strong>尚未新增內部人員</strong><span>請使用上方欄位建立第一個帳號</span></div>'}</div><div class="dialog-actions"><button type="button" class="secondary" data-member-close>關閉</button></div></div>`;dialog.querySelectorAll('[data-member-close]').forEach(button=>button.onclick=()=>dialog.close());dialog.querySelector('#cancelMemberEdit')?.addEventListener('click',()=>openGroupMembers(g));dialog.querySelectorAll('[data-member-edit]').forEach(button=>button.onclick=()=>openGroupMembers(g,button.dataset.memberEdit));dialog.querySelectorAll('[data-member-delete]').forEach(button=>button.onclick=()=>{const member=g.members.find(item=>item.id===button.dataset.memberDelete);if(!member||!confirm(`確定要刪除人員「${member.name}」嗎？`))return;g.members=g.members.filter(item=>item.id!==member.id);save();openGroupMembers(g)});dialog.querySelector('#groupMemberForm').onsubmit=event=>{event.preventDefault();const name=$('#groupMemberName').value.trim(),username=$('#groupMemberUsername').value.trim(),password=$('#groupMemberPassword').value;if(!name||!username||!password)return;const duplicate=allInternalMembers().find(member=>member.id!==editingId&&String(member.username||'').trim().toLowerCase()===username.toLowerCase());if(duplicate){alert('此登入帳號已被其他人員使用');return}if(editing&&String(editing.username||'').toLowerCase()==='rondo'&&username.toLowerCase()!=='rondo'&&!window.__omniplaySession?.bootstrap){alert('最高管理者帳號必須保留 Rondo');return}if(editing)Object.assign(editing,{name,username,password,updatedAt:new Date().toISOString()});else g.members.push({id:uid('member'),name,username,password,createdAt:new Date().toISOString()});save();openGroupMembers(g)};if(!dialog.open)dialog.showModal();setTimeout(()=>$('#groupMemberName')?.focus(),50)}
function openGroupManager(){if(!window.__omniplaySession?.superAdmin)return;const list=$('#groupManagerList');list.innerHTML='';if(!state.customerGroups.length)list.innerHTML='<div class="empty-mini"><div>👥</div><strong>尚無群組分類</strong><span>按下方按鈕新增第一個群組</span></div>';state.customerGroups.forEach(g=>{const count=state.customers.filter(u=>u.groupId===g.id).length,row=document.createElement('div');row.className='group-manager-row';row.innerHTML=`<div class="group-icon">👥</div><div class="group-manager-main"><strong>${esc(g.name)}</strong><span>${count} 個平台・可看 ${(g.allowedPages||[]).length} 個頁面</span></div><div class="group-manager-actions"><button type="button" class="group-members">人員管理</button><button type="button" class="group-permissions">權限設定</button><button type="button" class="group-edit">編輯</button><button type="button" class="group-delete" ${count?'disabled':''}>刪除</button></div>`;row.querySelector('.group-members').onclick=()=>openGroupMembers(g);row.querySelector('.group-permissions').onclick=()=>{$('#groupManagerDialog').close();editGroupPermissions(g)};row.querySelector('.group-edit').onclick=()=>{const name=prompt('編輯群組名稱：',g.name)?.trim();if(!name||name===g.name)return;if(state.customerGroups.some(group=>group.id!==g.id&&String(group.name||'').trim().toLowerCase()===name.toLowerCase())){alert('已有相同名稱的群組');return}g.name=name;save();openGroupManager()};const del=row.querySelector('.group-delete');if(count)del.title='請先將此群組的平台移到其他群組';del.onclick=()=>{if(count){alert(`「${g.name}」仍有 ${count} 個平台使用中，請先將平台移到其他群組。`);return}if(!confirm(`確定要刪除群組「${g.name}」嗎？\n刪除後無法復原。`))return;state.customerGroups=state.customerGroups.filter(group=>group.id!==g.id);save();openGroupManager()};list.append(row)});const dialog=$('#groupManagerDialog');if(!dialog.open)dialog.showModal()}
function editGroupPermissions(g){if(!window.__omniplaySession?.superAdmin)return;g.allowedPages||=[];
const w=$('#workspace');
w.innerHTML=`<div class="permission-top"><button id="backGroup" class="secondary">← 返回 ${esc(g.name)}</button></div><div class="admin-card permission-card"><div class="modal-head"><div><div class="eyebrow">GROUP PAGE ACCESS</div><h2>${esc(g.name)} 的群組權限</h2><p>依照「分類 → 頁面」顯示，勾選要開放給此群組查看的頁面。</p></div><div class="group-icon">👥</div></div><div id="permissionList" class="permission-list"></div><div class="permission-footer"><span id="permCount">已選 ${g.allowedPages.length} 個頁面</span><button id="savePerm" class="primary">儲存群組權限</button></div></div>`;
const l=$('#permissionList');
const total=workspacePageIds().length;
if(!total)l.innerHTML='<div class="empty-mini"><strong>目前沒有可設定的頁面</strong></div>';
if(isInternalGroup(g)){const section=document.createElement('section');section.className='permission-category';section.innerHTML=`<div class="permission-category-head"><span class="permission-category-icon">⚙️</span><strong>系統管理</strong><span class="permission-category-count">1 頁</span></div><div class="permission-category-pages"><label class="permission-row" data-page-id="${PLATFORM_LIST_PERMISSION}"><input type="checkbox" value="${PLATFORM_LIST_PERMISSION}" ${g.allowedPages.includes(PLATFORM_LIST_PERMISSION)?'checked':''}><span class="permission-icon">🏢</span><span><strong>所有平台列表</strong><small>管理平台、群組、人員與權限</small></span></label></div>`;l.append(section)}
const resourceEntries=customerSectionPages(),resourceById=new Map(resourceEntries.filter(entry=>entry.page).map((entry,index)=>[entry.page.id,{...entry,index}]));
state.categories.forEach(c=>{const pages=(c.pages||[]).filter(p=>isVisibleGroupPermissionPage(c,p)).sort((left,right)=>(resourceById.get(left.id)?.index??99)-(resourceById.get(right.id)?.index??99));
if(!pages.length)return;
const section=document.createElement('section');
section.className='permission-category';
section.innerHTML=`<div class="permission-category-head"><span class="permission-category-icon">📁</span><strong>${esc(c.displayName||c.name)}</strong><span class="permission-category-count">${pages.length} 頁</span></div><div class="permission-category-pages"></div>`;
const pageList=section.querySelector('.permission-category-pages');
const gameListEntry=resourceEntries.find(entry=>entry.category?.id===c.id&&entry.page?.customerOpGame);if(gameListEntry){const info=document.createElement('div');info.className='permission-row';info.style.background='#f4f8ff';info.innerHTML='<span style="width:18px;text-align:center;color:#54708f">✓</span><span class="permission-icon">'+gameListEntry.section.icon+'</span><span><strong>'+esc(customerSectionLabel(gameListEntry.section))+'</strong><small>依各遊戲的「可查看群組」設定顯示</small></span>';pageList.append(info)}
pages.forEach(p=>{const entry=resourceById.get(p.id);pageList.insertAdjacentHTML('beforeend',`<label class="permission-row" data-page-id="${p.id}"><input type="checkbox" value="${p.id}" ${g.allowedPages.includes(p.id)?'checked':''}><span class="permission-icon">${entry?entry.section.icon:icon(p.type)}</span><span><strong>${esc(entry?customerSectionLabel(entry.section):(p.displayName||p.name))}</strong><small>頁面</small></span></label>`)});
l.append(section)});
l.addEventListener('change',()=>$('#permCount').textContent=`已選 ${l.querySelectorAll('input:checked').length} 個頁面`);
$('#backGroup').onclick=renderCustomers;
$('#savePerm').onclick=async()=>{const rows=[...l.querySelectorAll('.permission-row[data-page-id]')],button=$('#savePerm'),allowedPages=rows.filter(x=>x.querySelector('input').checked).map(x=>x.dataset.pageId),pageOrder=rows.map(x=>x.dataset.pageId);
button.disabled=true;button.textContent='正在同步客戶權限…';
try{const permissionsUpdatedAt=await saveGroupPermissions(db,g.id,allowedPages,pageOrder);Object.assign(g,{allowedPages,pageOrder,permissionMode:'custom',permissionsUpdatedAt});$('#cloudStatus').textContent='☁️ 群組權限已同步到客戶端';renderCustomers();alert('已核對雲端客戶資料，群組權限同步完成')}catch(error){button.disabled=false;button.textContent='重試儲存群組權限';alert('權限同步失敗：'+firebaseError(error))}
}}
$('#customerBtn').onclick=renderCustomers;
function updateNewItemFields(){const createCategory=$('#newItemCategory').value==='__new__',createPage=!createCategory||$('#newItemCreatePage').checked;$('#newItemCategoryField').classList.toggle('hidden',!createCategory);$('#newItemCategoryName').required=createCategory;$('#newItemCategoryName').disabled=!createCategory;$('#newItemPageChoice').classList.toggle('hidden',!createCategory);$('#newItemPageFields').classList.toggle('hidden',!createPage);$('#pageName').required=createPage;$('#pageName').disabled=!createPage;$('#pageType').disabled=!createPage;}
function openNewItem(){if(!isAdminWorkspaceView())return;$('#newItemCategory').innerHTML=state.categories.map(category=>`<option value="${esc(category.id)}">${esc(category.displayName||category.name)}</option>`).join('')+'<option value="__new__">＋ 新增分類…</option>';$('#newItemCategory').value=state.categories.some(c=>c.id===state.activeCategoryId)?state.activeCategoryId:(state.categories[0]?.id||'__new__');$('#pageName').value='';$('#newItemCategoryName').value='';$('#newItemCreatePage').checked=true;updateNewItemFields();$('#pageDialog').showModal();}
$('#addCategoryBtn').onclick=openNewItem;
$('#addPageBtn').onclick=openNewItem;
$('#newItemCategory').onchange=updateNewItemFields;
$('#newItemCreatePage').onchange=updateNewItemFields;
$('#pageForm').onsubmit=e=>{e.preventDefault();if(!isAdminWorkspaceView())return;const createCategory=$('#newItemCategory').value==='__new__',createPage=!createCategory||$('#newItemCreatePage').checked;const name=$('#newItemCategoryName').value.trim(),n=$('#pageName').value.trim(),t=$('#pageType').value;if(createCategory&&!name||createPage&&!n)return;
let c=state.categories.find(category=>category.id===$('#newItemCategory').value);if(createCategory){c=state.categories.find(category=>category.name.trim()===name);if(!c){c={id:uid('cat'),name,pages:[]};state.categories.push(c)}}if(!c)return;c.pages||=[];state.activeCategoryId=c.id;state.activePageId=null;
if(createPage){const p={id:uid('page'),name:n,type:t,createdAt:new Date().toISOString()};if(t!=='sheet'){p.files=[];p.folders=[]}c.pages.push(p);state.customerGroups.forEach(group=>{if(window.__omniplaySession?.superAdmin&&group.permissionMode==='all'&&isDefaultGroupPermissionPage(c,p)){group.allowedPages||=[];group.pageOrder||=[];if(!group.allowedPages.includes(p.id))group.allowedPages.push(p.id);if(!group.pageOrder.includes(p.id))group.pageOrder.push(p.id)}});state.activePageId=p.id}
save();$('#pageDialog').close();renderNav();renderPage()};
$('#groupForm').onsubmit=e=>{e.preventDefault();
const n=$('#groupName').value.trim();
if(!n)return;
state.customerGroups.push(newCustomerGroup(n));
save();
$('#groupDialog').close();
renderCustomers()};
$('#addManagedGroup').onclick=()=>{const name=prompt('新增群組分類名稱：')?.trim();if(!name)return;if(state.customerGroups.some(g=>g.name===name)){alert('已有相同名稱的群組');return}state.customerGroups.push(newCustomerGroup(name));save();openGroupManager()};
document.querySelectorAll('.add-option').forEach(b=>b.onclick=()=>{const target=b.dataset.target,isType=target==='customerType',isCommApp=target==='customerCommApp',isGroup=target==='customerGroup',label=isType?'客戶群組':isCommApp?'通訊 APP':isGroup?'所屬群組':'對接進度',value=prompt(`新增${label}選項：`)?.trim();
if(!value)return;
if(isGroup){let group=state.customerGroups.find(g=>g.name===value);if(!group){group=newCustomerGroup(value);state.customerGroups.push(group)}const sel=$('#customerGroup');sel.innerHTML=state.customerGroups.map(g=>`<option value="${g.id}">${esc(g.name)}</option>`).join('');sel.value=group.id}else{const items=isType?state.customerTypeOptions:isCommApp?state.customerCommAppOptions:state.customerProgressOptions;if(!items.includes(value))items.push(value);fillCustomerOptionSelect(`#${target}`,items);$(`#${target}`).value=value}
save()});
$('#customerForm').onsubmit=e=>{e.preventDefault();
const name=$('#customerName').value.trim(),sel=$('#customerGroup'),groupId=sel.value;
if(!name)return;
const existing=editingCustomerId?state.customers.find(customer=>customer.id===editingCustomerId):null,inputDate=$('#customerLaunchDate').value.trim(),data={name,domain:$('#customerDomain').value.trim(),customerType:$('#customerType').value,groupId,progress:$('#customerProgress').value,launchDate:inputDate||((existing?.launchDate&&!/^\d{4}-\d{2}-\d{2}$/.test(existing.launchDate))?existing.launchDate:''),notes:$('#customerNotes').value.trim()};
if(existing)Object.assign(existing,data);else state.customers.push({id:uid('usr'),...data});
editingCustomerId=null;
save();
$('#customerDialog').close();
renderCustomers()};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>{const d=document.getElementById(b.dataset.close);
if(d?.id==='customerDialog'){editingCustomerId=null;const s=$('#customerGroup');
s.disabled=false;
delete s.dataset.lockedGroup}d?.close()});
window.addEventListener('beforeunload',()=>{dispose();
saveNow()});
load();



